 ('7285a96d-0ce7-475c-a35d-666ffa6220cb', 'Vote et dépouillement — élections des représentants', 'Aux écoles. Le dépouillement suit immédiatement le vote.', '', 'ecole', 'tous', '2026-10-02', '16:30', '2026-10-02', NULL, 0, 0, 'd9012263-31f9-4e11-b98e-ec93be036736', '2026-09-09T13:20:00.000Z', 'd9012263-31f9-4e11-b98e-ec93be036736', '2026-09-09T13:20:00.000Z'),
 ('4a92d225-de8f-4012-a99e-9c7e6def8894', 'Réunion de préparation des conseils d''école', 'Réunion commune à l''élémentaire et à la maternelle.

